<?php session_start();require 'page-guard.php';require '../config/db_conn.php';if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){http_response_code(400);exit('Invalid request.');}$action=$_POST['action']??'';if($action==='password'){$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$user=$_SESSION['admin-user']??'admin@gmail.com';$stmt=$conn->prepare('SELECT ADMIN_PASS FROM admins WHERE ADMIN_USER=?');$stmt->bind_param('s',$user);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();if(!$row||!password_verify($current,$row['ADMIN_PASS'])||strlen($new)<8||$new!==$confirm)exit('Current password is incorrect or new passwords do not match.');$hash=password_hash($new,PASSWORD_DEFAULT);$up=$conn->prepare('UPDATE admins SET ADMIN_PASS=? WHERE ADMIN_USER=?');$up->bind_param('ss',$hash,$user);$up->execute();$_SESSION['toast']=['message'=>'Administrator password updated successfully.','type'=>'success'];}elseif($action==='add_section'){$section=trim($_POST['section']??'');if($section==='')exit('Section is required.');$conn->query("CREATE TABLE IF NOT EXISTS sections (SECTION_ID INT AUTO_INCREMENT PRIMARY KEY, SECTION VARCHAR(80) NOT NULL UNIQUE)");$add=$conn->prepare('INSERT IGNORE INTO sections (SECTION) VALUES (?)');$add->bind_param('s',$section);$add->execute();$_SESSION['toast']=['message'=>'Section added and available for teacher assignment.','type'=>'success'];}elseif($action==='rename_section'){$old=trim($_POST['old_section']??'');$new=trim($_POST['section']??'');if($old===''||$new==='')exit('Section is required.');$conn->query("CREATE TABLE IF NOT EXISTS sections (SECTION_ID INT AUTO_INCREMENT PRIMARY KEY, SECTION VARCHAR(80) NOT NULL UNIQUE)");$up=$conn->prepare('UPDATE students SET SECTION=? WHERE SECTION=?');$up->bind_param('ss',$new,$old);$up->execute();$rename=$conn->prepare('UPDATE sections SET SECTION=? WHERE SECTION=?');$rename->bind_param('ss',$new,$old);$rename->execute();$_SESSION['toast']=['message'=>'Section updated successfully.','type'=>'success'];}header('Location: settings.php');exit;
